const { Client } = require('discord.js');
const client = new Client({ intents: ['GUILDS', 'GUILD_MESSAGES'] });

client.on('ready', () => {
  console.log(`Logged in as ${client.user.tag}`);
});

client.login('your-token-here');
```
3. Register the `ban` command by creating a new file named `commands/ban.js`:
```javascript
module.exports = {
  data: {
    name: 'ban',
    description: 'Ban a member',
    options: [
      {
        type: 'USER',
        name: 'target',
        description: 'The target member to ban',
        required: true,
      },
      {
        type: 'STRING',
        name: 'reason',
        description: 'The reason for the ban',
      },
    ],
  },
  async execute(interaction) {
    const target = interaction.options.getUser('target');
    const member = interaction.guild.members.cache.get(target.id);
    const reason = interaction.options.getString('reason') || 'No reason provided';

    if (!member) {
      return interaction.reply(`Cannot find user with ID ${target.id}.`);
    }

    try {
      await member.ban({ reason });
      interaction.reply(`Successfully banned ${target.username} (${target.id}) for ${reason}.`);
    } catch (error) {
      console.error(error);
      interaction.reply('An error occurred while banning the user.');
    }
  },
};
```
