#include <iostream>
#include <string>
#include <algorithm>

std::string convertMarkdownToHTML(const std::string& markdown) {
    // Define the conversion rules here
    // ...

    // Convert the markdown string to HTML
    std::string html = "<html>\n<body>\n";
    std::string currentLine;
    bool isInCodeBlock = false;

    for (char c : markdown) {
        if (c == '`') {
            if (!isInCodeBlock) {
                isInCodeBlock = true;
            } else {
                isInCodeBlock = false;
            }
        } else if (c == '\n') {
            if (isInCodeBlock) {
                currentLine += c;
            } else {
                if (!currentLine.empty()) {
                    if (currentLine.back() != '.') {
                        html += " ";
                    }
                    html += "</p>\n";
                }
                html += "<p>";
                currentLine.clear();
            }
        } else {
            currentLine += c;
        }
    }

    if (!currentLine.empty()) {
        if (currentLine.back() != '.') {
            html += " ";
        }
        html += "</p>\n";
    }

    html += "</body>\n</html>";

    return html;
}

int main() {
    std::string markdown = "# Hello, World!\n\nThis is some *markdown* formatted text.\n\n```cpp\nint main() {\n    std::cout << "Hello, World!";\n}\n```";

